export type BrandName = keyof typeof BRANDS;

/** How much of the icon's height the longest side of a mark fills, at optical 1. */
const FILL = 0.86;

/**
 * The mark centred in a box as tall as the icon, and only as wide as the mark,
 * so the gap to the word after it is the same for a leaf as for a whale.
 */
function viewBox({ box: [x, y, w, h], optical = 1 }: Brand): string {
  const side = Math.max(w, h);
  const height = side / (FILL * optical);
  const pad = (height - side) / 2;
  return [x - pad, y + h / 2 - height / 2, w + pad * 2, height].map((n) => +n.toFixed(2)).join(' ');
}

/** Each brand's names as whole words: not 'CSS' in 'PostCSS', nor 'conda' in 'Anaconda'. */
const NAMES = (Object.keys(BRANDS) as BrandName[]).flatMap((key) => {
  const brand: Brand = BRANDS[key];
  return [brand.name, ...(brand.aliases ?? [])].map((name) => {
    const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    return [key, new RegExp(`(?<!\\w)${escaped}(?!\\w)`, 'g')] as const;
  });
});

/**
 * The brand a label names, if any: 'Python' → python, 'Claude Haiku 4.5' →
 * claude, 'OpenAI hackathon' → openai. 'Graphs' or 'RAG' → undefined.
 *
 * A name inside a longer one counts as the longer: 'GitHub Actions' is GitHub
 * Actions, not GitHub, and 'Tailwind CSS' is Tailwind, not CSS. A label that
 * still names more than one brand gets no mark, since one would claim the whole
 * label for one of them: 'HTML/CSS/JavaScript', 'Anaconda / conda'.
 */
export function brandFor(label: string): BrandName | undefined {
  const found = NAMES.flatMap(([key, pattern]) =>
    Array.from(label.matchAll(pattern), (m) => ({ key, start: m.index, end: m.index + m[0].length })),
  );
  const named = new Set(
    found
      .filter((a) => !found.some((b) => b.start <= a.start && a.end <= b.end && b.end - b.start > a.end - a.start))
      .map((a) => a.key),
  );
  return named.size === 1 ? [...named][0] : undefined;
}

export default function BrandIcon({ name, className }: { name: BrandName; className?: string }) {
  const brand: Brand = BRANDS[name];
  const id = `brand${useId().replace(/[^\w-]/g, '')}`;
  const markup = [
    brand.credit ? `<!-- ${brand.credit} -->` : '',
    brand.defs ? `<defs>${brand.defs}</defs>` : '',
    /* both versions are drawn; the theme shows one (styles/site.css "Brand icons") */
    brand.dark ? `<g class="brand-light">${brand.art}</g><g class="brand-dark">${brand.dark}</g>` : brand.art,
  ].join('');
  return (
    <svg
      className={className ? `brand-icon ${className}` : 'brand-icon'}
      viewBox={viewBox(brand)}
      aria-hidden="true"
      dangerouslySetInnerHTML={{ __html: markup.replace(/\{id\}/g, id) }}
    />
  );
}
